def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline bid depends on my HP pressure
    if my_hp <= 2.0:
        base = DAILY_SALARY * 0.9
    elif my_hp <= 4.0 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # Use yesterday's max/median to avoid getting outbid by high-pressure players
    if prev_bids:
        prev_max = max(prev_bids)
        prev_min = min(prev_bids)
        prev_sorted = sorted(prev_bids)
        mid = int(len(prev_sorted) // 2)
        prev_median = float(prev_sorted[mid])

        # If others bid aggressively (>= ~0.85 salary), we slightly undercut
        if prev_max >= DAILY_SALARY * 0.85:
            # Keep below their top pressure but above low bids
            target = min(prev_max - 5.0, max(base, prev_median + 5.0))
        else:
            # If yesterday was calmer, bid around median plus a small premium
            target = max(base, prev_median + 2.0)

        # If there was a very low outlier (like Cindy), don't chase it; stay near median
        if prev_min <= DAILY_SALARY * 0.5:
            target = max(target, prev_median + 3.0)

    else:
        target = base

    # Supply context: with higher supply, competition for water is less critical; bid slightly lower.
    # Normalize supply into [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    t = 0.0 if t < 0.0 else (1.0 if t > 1.0 else t)

    # When supply is high, reduce bid; when low, increase slightly
    supply_adjust = 1.0 + (0.08 * (0.5 - t))
    target *= supply_adjust

    # Final clamp to budget and a reasonable upper bound
    target = float(target)
    if my_budget <= 0.0:
        return 0.0

    # Ensure we don't bid above budget
    bid = min(my_budget, target)

    # If my budget is tiny, still bid what I can
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
                rich_opp += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive:
        base = DAILY_SALARY * 0.28
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    units = int(supply // WATER_REQ)
    scarcity = units <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if hp <= 2 or no_water_days >= 2:
        emergency = max(DAILY_SALARY * 0.98, highest_prev + 3.0)
        return float(max(0.0, min(budget, emergency)))

    if hp <= 4 or no_water_days >= 1:
        if scarcity:
            bid = max(DAILY_SALARY * 0.82, min(highest_prev + 2.0, DAILY_SALARY * 1.02))
        else:
            bid = max(DAILY_SALARY * 0.62, min(highest_prev + 1.5, DAILY_SALARY * 0.9))
        return float(max(0.0, min(budget, bid)))

    if scarcity:
        if highest_prev >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.22
        elif highest_prev >= DAILY_SALARY * 0.95:
            bid = DAILY_SALARY * 0.46
        else:
            bid = max(DAILY_SALARY * 0.58, highest_prev + 1.2)
    else:
        if highest_prev >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.18
        elif avg_prev >= DAILY_SALARY * 0.9:
            bid = DAILY_SALARY * 0.3
        else:
            bid = max(DAILY_SALARY * 0.34, min(avg_prev + 1.0, DAILY_SALARY * 0.62))

    if rich_opp >= 2 and scarcity:
        bid *= 0.9
    if urgent_opp >= 2 and scarcity:
        bid *= 1.08
    if day >= 8 and hp >= 7:
        bid *= 0.9

    bid = max(0.0, min(budget, bid))
    return float(bid)

