def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    TOTAL_EPISODE_DAYS = 10

    CRITICAL_HP_THRESHOLD = 3
    HIGH_BID_THRESHOLD_RATIO = 0.85

    base_bid_ratio = 0.55
    low_hp_bid_ratio = 0.95
    no_opponent_bid_ratio = 0.4
    conserve_bid_ratio = 0.3
    moderate_competition_bid_ratio = 0.7

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    current_day = day_context['day']

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * no_opponent_bid_ratio)

    if my_status['hp'] <= CRITICAL_HP_THRESHOLD:
        return min(my_status['budget'], DAILY_SALARY * low_hp_bid_ratio)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * HIGH_BID_THRESHOLD_RATIO:
            if num_alive_opponents >= 3:
                return min(my_status['budget'], max(DAILY_SALARY * 0.75, highest_prev_bid + 2.0))
            else:
                return min(my_status['budget'], DAILY_SALARY * conserve_bid_ratio)
        else:
            return min(my_status['budget'], max(DAILY_SALARY * base_bid_ratio, highest_prev_bid + 1.5))
    else:
        if current_day == 1:
            if num_alive_opponents >= 3:
                return min(my_status['budget'], DAILY_SALARY * moderate_competition_bid_ratio)
            else:
                return min(my_status['budget'], DAILY_SALARY * base_bid_ratio)
        else:
            return min(my_status['budget'], DAILY_SALARY * base_bid_ratio)
